//! Raw dataset assignments use exact native names and observed attribute transactions.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><p id=target></p><svg id=svg></svg></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://dataset-inspection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn dataset_raw_assignment_exact_names_values_attr_identity_and_live_inspection(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;for(var pair of [['a\ud800Z','data-a\ud800-z'],['a\udfffZ','data-a\udfff-z'],['\ud800','data-\ud800'],['pair\ud800\ud800','data-pair\ud800\ud800'],['x-\ud800B','data-x-\ud800-b']]){var key=pair[0],name=pair[1],raw='v\udfff'+key;d[key]=raw;var a=n.getAttributeNodeNS(null,name),desc=Object.getOwnPropertyDescriptor(d,key);if(n.getAttributeNS(null,name)!==raw||a.value!==raw||d[key]!==raw||!Object.hasOwn(d,key)||!(key in d)||desc.value!==raw||!desc.writable||!desc.enumerable||!desc.configurable)throw 'exact native named write';d[key]='replaced';if(a!==n.getAttributeNodeNS(null,name)||a.value!=='replaced')throw 'same native Attr';delete d[key];if(a.ownerElement!==null||Object.hasOwn(d,key))throw 'native deletion after write';}d['x\ud800']='raw';d['x\ufffd']='scalar';if(d['x\ud800']!=='raw'||d['x\ufffd']!=='scalar')throw 'projection separation';"#);}

#[test]
fn dataset_raw_assignment_html_namespace_separation_and_svg_producer_refusal(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),data=n.dataset;n.setAttributeNS('urn:foreign','q:data-x\ud800','foreign');data['x\ud800']='main\udfff';if(n.getAttributeNS(null,'data-x\ud800')!=='main\udfff'||data['x\ud800']!=='main\udfff'||n.getAttributeNS('urn:foreign','data-x\ud800')!=='foreign')throw 'actual namespace separation';var svg=document.getElementById('svg'),svgData=svg.dataset;svgData['x\ud800']='accepted';if(svgData['x\ud800']!=='accepted'||svg.getAttributeNS(null,'data-x\ud800')!=='accepted')throw 'actual SVG raw name with scalar value';"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let error=p.runtime.execute(r#"svgData['x\ud800']='refused\udfff';"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("Unpaired attribute DOMString integration"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);run(&mut d,&mut f,&mut p,"svgData.recovery='actual';if(svg.getAttribute('data-recovery')!=='actual')throw 'existing SVG producer recovery';");}

#[test]
fn dataset_raw_assignment_key_then_value_binding_once_and_abrupt_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,order='',key={toString:function(){order+='k';return 'x\ud800Z';}},value={toString:function(){order+='v';return 'raw\udfff';}};d[key]=value;if(order!=='kv'||d['x\ud800Z']!=='raw\udfff')throw 'binding order once';var marker={},error;try{d['bad\ud800-x']={toString:function(){n.setAttribute('data-author','effect');throw marker;}};}catch(e){error=e;}if(error!==marker||d.author!=='effect')throw 'same abrupt identity and actual author effect';var calls=0;try{d[{toString:function(){throw marker;}}]={toString:function(){calls++;return 'x';}};}catch(e){if(e!==marker)throw 'key identity';}if(calls)throw 'abrupt key precedes value';"#);}

#[test]
fn dataset_raw_assignment_errors_follow_value_conversion_without_mutation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,watch=new MutationObserver(function(){});watch.observe(n,{attributes:true});for(var pair of [['x\ud800-y','SyntaxError'],['x\ud800 y','InvalidCharacterError'],['x\ud800/y','InvalidCharacterError'],['x\ud800=y','InvalidCharacterError'],['x\ud800\u0000','InvalidCharacterError']]){var calls=0,error;try{d[pair[0]]={toString:function(){calls++;return 'value';}};}catch(e){error=e;}if(calls!==1||!(error instanceof DOMException)||error.name!==pair[1])throw 'converted value before native name exception';}var error;try{d['x\ud800-y']=Symbol('value');}catch(e){error=e;}if(!(error instanceof TypeError))throw 'Symbol value binding precedes syntax';if(watch.takeRecords().length||n.getAttributeNS(null,'data-x\ud800-y')!==null)throw 'no invalid native mutation';d['x\ud800']='recovered';if(d['x\ud800']!=='recovered')throw 'recovery';"#);}

#[test]
fn dataset_raw_assignment_overrides_inherited_setters_and_author_native_method_shadow(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,hits=0;Object.defineProperty(DOMStringMap.prototype,'x\ud800',{get:function(){return 'author';},set:function(){hits++;throw 'prototype setter';},configurable:true});n.setAttribute=function(){throw 'author method';};n.setAttributeNS=function(){throw 'author namespace method';};d['x\ud800']='native';if(hits||d['x\ud800']!=='native'||n.getAttributeNS(null,'data-x\ud800')!=='native')throw 'native named setter transaction';delete d['x\ud800'];if(d['x\ud800']!=='author')throw 'prototype remains separate';"#);}

#[test]
fn dataset_raw_assignment_observers_receive_real_raw_name_and_previous_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,watch=new MutationObserver(function(){});watch.observe(n,{attributes:true,attributeOldValue:true});d['x\ud800Z']='first\udfff';var a=n.getAttributeNodeNS(null,'data-x\ud800-z');d['x\ud800Z']='last\ud800';var r=watch.takeRecords();if(r.length!==2||r[0].target!==n||r[1].target!==n||r[0].attributeName!=='data-x\ud800-z'||r[1].attributeName!=='data-x\ud800-z'||r[0].attributeNamespace!==null||r[0].oldValue!==null||r[1].oldValue!=='first\udfff'||a.value!=='last\ud800')throw 'actual raw native observation';"#);}

#[test]
fn dataset_raw_assignment_copy_storage_refusal_is_atomic_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),data=n.dataset;n.setAttributeNS(null,'data-x\ud800','old\udfff');var watch=new MutationObserver(function(){});watch.observe(n,{attributes:true,attributeOldValue:true});"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;for copy in [true,false]{p.begin_job();if copy{p.state.copy_work=0;}else{p.state.retained_limit=p.state.retained;}let error=p.runtime.execute(&format!(r#"data['x\ud800']='{}';"#,"refused".repeat(200)),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains(if copy{"string work"}else{"retained"}),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,r#"if(watch.takeRecords().length||data['x\ud800']!=='old\udfff')throw 'atomic refusal';"#);}run(&mut d,&mut f,&mut p,r#"data['x\ud800']='recovered';var r=watch.takeRecords();if(r.length!==1||r[0].oldValue!=='old\udfff'||data['x\ud800']!=='recovered')throw 'native recovery';"#);}

#[test]
fn dataset_raw_assignment_native_preparation_work_deadline_refusal_preserves_state(){let(mut d,mut f,mut p)=fixture();let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("target")).unwrap();let handle=DATASET_BASE+node as u32;let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for expired in [false,true]{p.begin_job();if expired{p.state.execution_deadline=Some(Instant::now());}else{p.state.host_work=0;}assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.named_units_assignment(handle,&[120,0xd800]).is_err());p.state.execution_deadline=None;p.begin_job();assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.named_units_assignment(handle,&[120,0xd800]).unwrap(),crate::javascript::NativeNamedAssignment::Attribute{..}));assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}}
